/* The names of the fields the flag log records, and of their Enum choices (flagnames.c, generated by
 * tools/gendata.py from data/gamedata_fields.json). About half the fields have a known name. */
#ifndef FLAGNAMES_H
#define FLAGNAMES_H

#include <stdint.h>

typedef struct { uint32_t hash; const char *name; } flagname_t;               /* sorted by hash */
typedef struct { uint32_t field, choice; const char *name; } flagchoice_t;    /* sorted by field, then choice */

extern const int flagnames_count;
extern const flagname_t flagnames[];
extern const int flagchoices_count;
extern const flagchoice_t flagchoices[];

/* the field's name, or 0 if it isn't known */
const char *flagname(uint32_t hash);
/* an Enum field's choice name, or 0 */
const char *flagchoice(uint32_t field, uint32_t choice);

#endif
